// src/components/profile/ProfileCompletePage.js
import React, { useState, useEffect, useRef } from "react";
import { useNavigate } from "react-router-dom";
import { toast } from "sonner";
import { useAuth } from "../../context/AuthContext";
import { StepProgress } from "../ui/StepProgress";
import { Progress } from "../ui/progress";
import { saveProfile, getProfile } from "../../api/listingService";
import OwnerProfileForm from "./OwnerProfileForm";

import {
    FaUser, FaHome, FaUtensils,
    FaLeaf, FaDrumstickBite, FaTruck, FaUtensilSpoon, FaRandom, FaCheck
} from "react-icons/fa";

import { Input } from "../ui/input";
import { Label } from "../ui/label";
import { Button } from "../ui/button";
import { Card, CardContent } from "../ui/card";
import { Slider } from "../ui/slider";

import { Autocomplete } from '@react-google-maps/api';
import { useGoogleMaps } from '../../context/GoogleMapsContext';

const ROOM_AMENITIES = [
    { id: "wifi", label: "WiFi" },
    { id: "electricity", label: "24/7 Electricity" },
    { id: "mineral_water", label: "Mineral Water" },
    { id: "hot_cold_water", label: "Hot/Cold Water" },
    { id: "laundry", label: "Laundry" },
    { id: "ac", label: "AC" },
    { id: "parking", label: "Parking" },
    { id: "bed", label: "Bed" },
    { id: "study_table", label: "Study Table" },
    { id: "security", label: "Security" },
    { id: "kitchen", label: "Kitchen" },
];

const ROOM_TYPES = [
    { id: "private", label: "Private Room" },
    { id: "shared-2", label: "2 Sharing" },
    { id: "shared-3+", label: "3+ Sharing" },
];

const parseBudgetString = (budgetStr) => {
    if (!budgetStr) return 5000;
    const match = String(budgetStr).match(/(\d+)\s*[-–—to]+\s*(\d+)/i);
    if (match) return Math.round((parseInt(match[1]) + parseInt(match[2])) / 2);
    const num = parseInt(budgetStr);
    if (!isNaN(num)) return num;
    return 5000;
};

const ProfileCompletePage = () => {
    const navigate = useNavigate();
    const { user, refreshProfileStatus } = useAuth();

    const isOwner = user?.role === 'owner';

    const [currentStep, setCurrentStep] = useState(0);
    const [loading, setLoading] = useState(false);
    const [isInitialLoad, setIsInitialLoad] = useState(true);
    const [formData, setFormData] = useState({
        personal: {
            firstName: "",
            lastName: "",
            email: "",
            phone: "",
            college: "",
            address: "",
            gender: "",
            altPhone: "",
            collegeAddress: "",
            collegeLat: null,
            collegeLng: null,
        },
        room: {
            roomType: "",
            budget: 5000,
            amenities: []
        },
        mess: {
            budget: 3500,
            foodPref: "",
            serviceType: "",
        },
    });

    const steps = isOwner ? [
        { id: "personal", title: "Personal Details" },
        { id: "business", title: "Business Details" },
        { id: "review", title: "Review" },
    ] : [
        { id: "personal", title: "Personal Details" },
        { id: "room", title: "Room Questions" },
        { id: "mess", title: "Mess Questions" },
        { id: "review", title: "Review" },
    ];

    const { isLoaded: isMapsLoaded } = useGoogleMaps();

    const collegeAutocompleteRef = useRef(null);

    useEffect(() => {
        const loadProfileData = async () => {
            if (!user) return;

            const cognitoData = {
                firstName: user?.given_name || "",
                lastName: user?.family_name || "",
                email: user?.email || "",
                phone: user?.phone || user?.["custom:phone"] || "",
            };

            let savedProfile = null;
            try {
                savedProfile = await getProfile();
            } catch (error) {
                // No saved profile found
            }

            const mergedPersonal = {
                ...cognitoData,
                ...savedProfile?.personal,
                firstName: savedProfile?.personal?.firstName || cognitoData.firstName,
                lastName: savedProfile?.personal?.lastName || cognitoData.lastName,
                email: savedProfile?.personal?.email || cognitoData.email,
                phone: savedProfile?.personal?.phone || cognitoData.phone,
            };

            if (isOwner) {
                setIsInitialLoad(false);
            } else {
                const savedRoom = savedProfile?.room || {};
                const roomBudget = savedRoom.budget ? parseBudgetString(savedRoom.budget) : 5000;

                setFormData({
                    personal: mergedPersonal,
                    room: {
                        roomType: savedRoom.roomType || "",
                        budget: roomBudget,
                        amenities: savedRoom.amenities || []
                    },
                    mess: savedProfile?.mess || {
                        budget: 3500,
                        foodPref: "vegetarian",
                        serviceType: "tiffin",
                    },
                });
                setIsInitialLoad(false);
            }
        };

        loadProfileData();
    }, [user, isOwner]);

    if (isOwner) {
        if (isInitialLoad) return (
            <div className="min-h-screen bg-muted flex items-center justify-center">
                <div className="space-y-4 w-full max-w-md">
                    <div className="h-8 w-48 bg-gray-200 rounded animate-pulse mx-auto"></div>
                    <div className="h-64 bg-gray-200 rounded-xl animate-pulse"></div>
                </div>
            </div>
        );

        return (
            <div className="min-h-screen bg-muted">
                <OwnerProfileForm
                    user={user}
                    onComplete={() => navigate("/profile/view")}
                />
            </div>
        );
    }

    const handleNext = () => {
        if (currentStep === 0 && !validatePersonal()) return;
        if (currentStep === 1 && !validateRoom()) return;
        if (currentStep === 2 && !validateMess()) return;
        setCurrentStep((prev) => prev + 1);
    };

    const handleBack = () => {
        if (currentStep > 0) setCurrentStep((prev) => prev - 1);
    };

    const validatePersonal = () => {
        const { firstName, lastName, email, phone, college, collegeAddress, gender } = formData.personal;
        if (!firstName || !lastName || !email || !phone || !college || !collegeAddress || !gender) {
            toast.error("Please fill all required fields");
            return false;
        }
        if (phone.length !== 10 || !/^\d+$/.test(phone)) {
            toast.error("Phone number must be exactly 10 digits");
            return false;
        }
        if (formData.personal.altPhone && (formData.personal.altPhone.length !== 10 || !/^\d+$/.test(formData.personal.altPhone))) {
            toast.error("Alternate phone must be exactly 10 digits");
            return false;
        }
        return true;
    };

    const validateRoom = () => {
        if (!formData.room.roomType) {
            toast.error("Please select a room type");
            return false;
        }
        return true;
    };

    const validateMess = () => {
        if (!formData.mess.foodPref || !formData.mess.serviceType) {
            toast.error("Please select food preference and service type");
            return false;
        }
        return true;
    };

    const handlePersonalChange = (e) => {
        const { name, value } = e.target;
        if (name === 'phone' || name === 'altPhone') {
            const numeric = value.replace(/\D/g, '');
            setFormData((prev) => ({
                ...prev,
                personal: { ...prev.personal, [name]: numeric },
            }));
            return;
        }
        setFormData((prev) => ({
            ...prev,
            personal: { ...prev.personal, [name]: value },
        }));
    };

    const handleCollegePlaceSelect = () => {
        const place = collegeAutocompleteRef.current?.getPlace();
        if (place && place.geometry) {
            setFormData((prev) => ({
                ...prev,
                personal: {
                    ...prev.personal,
                    collegeAddress: place.formatted_address || place.name,
                    collegeLat: place.geometry.location.lat(),
                    collegeLng: place.geometry.location.lng(),
                },
            }));
        }
    };

    const handleRoomBudgetChange = (val) => {
        setFormData((prev) => ({
            ...prev,
            room: { ...prev.room, budget: Number(val) },
        }));
    };

    const handleMessBudgetChange = (val) => {
        setFormData((prev) => ({
            ...prev,
            mess: { ...prev.mess, budget: Number(val) },
        }));
    };

    const handleSubmit = async () => {
        try {
            setLoading(true);
            const payload = {
                profileType: "completed",
                personal: formData.personal,
                room: formData.room,
                mess: formData.mess,
            };

            const response = await saveProfile(payload);

            if (!response) {
                throw new Error('Profile was not saved correctly. Please try again.');
            }

            await refreshProfileStatus();
            toast.success("Profile completed successfully!");
            navigate("/profile/view");
        } catch (error) {
            toast.error(error.message || "Failed to submit profile");
        } finally {
            setLoading(false);
        }
    };

    const handleSaveDraft = async () => {
        try {
            setLoading(true);
            const payload = {
                profileType: "draft",
                personal: formData.personal,
                room: formData.room,
                mess: formData.mess,
            };
            await saveProfile(payload);
            toast.success("Profile saved as draft!");
        } catch (error) {
            toast.error(error.message || "Failed to save draft");
        } finally {
            setLoading(false);
        }
    };

    const renderStepContent = () => {
        switch (currentStep) {
            case 0:
                return (
                    <div className="space-y-6">
                        <div className="bg-green-50 p-6 rounded-2xl border border-green-100 shadow-sm">
                            <h3 className="text-xl font-semibold mb-4 text-green-800 flex items-center">
                                <span className="bg-green-100 p-2 rounded-lg mr-3">
                                    <FaUser className="h-5 w-5 text-green-600" />
                                </span>
                                Personal Details
                            </h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div>
                                    <Label htmlFor="firstName" className="mb-1">First Name *</Label>
                                    <Input id="firstName" name="firstName" value={formData.personal.firstName} onChange={handlePersonalChange} disabled />
                                </div>
                                <div>
                                    <Label htmlFor="lastName" className="mb-1">Last Name *</Label>
                                    <Input id="lastName" name="lastName" value={formData.personal.lastName} onChange={handlePersonalChange} disabled />
                                </div>
                            </div>
                            <div className="mt-4">
                                <Label htmlFor="email" className="mb-1">Email Address *</Label>
                                <Input id="email" name="email" type="email" value={formData.personal.email} onChange={handlePersonalChange} disabled />
                            </div>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mt-4">
                                <div>
                                    <Label htmlFor="phone" className="mb-1">Phone No. *</Label>
                                    <Input id="phone" name="phone" type="tel" value={formData.personal.phone} onChange={handlePersonalChange} maxLength={10} placeholder="10 digit number" />
                                </div>
                                <div>
                                    <Label htmlFor="altPhone" className="mb-1">Alternative No.</Label>
                                    <Input id="altPhone" name="altPhone" type="tel" value={formData.personal.altPhone} onChange={handlePersonalChange} maxLength={10} placeholder="10 digit number" />
                                </div>
                            </div>
                            <div className="mt-4">
                                <Label htmlFor="address" className="mb-1">Personal Address *</Label>
                                <Input id="address" name="address" value={formData.personal.address} onChange={handlePersonalChange} />
                            </div>
                            <div className="mt-4">
                                <Label htmlFor="college" className="mb-1">College Name *</Label>
                                <Input id="college" name="college" value={formData.personal.college} onChange={handlePersonalChange} />
                            </div>
                            <div className="mt-4">
                                <Label htmlFor="collegeAddress" className="mb-1">College Address *</Label>
                                {isMapsLoaded ? (
                                    <Autocomplete
                                        onLoad={(autocomplete) => { collegeAutocompleteRef.current = autocomplete; }}
                                        onPlaceChanged={handleCollegePlaceSelect}
                                    >
                                        <Input
                                            id="collegeAddress"
                                            name="collegeAddress"
                                            value={formData.personal.collegeAddress}
                                            onChange={handlePersonalChange}
                                            placeholder="Search your college location..."
                                        />
                                    </Autocomplete>
                                ) : (
                                    <Input
                                        id="collegeAddress"
                                        name="collegeAddress"
                                        value={formData.personal.collegeAddress}
                                        onChange={handlePersonalChange}
                                        placeholder="Enter college address..."
                                    />
                                )}
                            </div>
                            <div className="mt-4">
                                <Label className="mb-2">Gender</Label>
                                <div className="flex gap-4">
                                    {["male", "female", "other"].map((gender) => (
                                        <div
                                            key={gender}
                                            className={`flex items-center space-x-2 p-2 border rounded cursor-pointer hover:bg-gray-50 ${formData.personal.gender === gender ? "border-blue-500 bg-blue-50" : ""}`}
                                            onClick={() => setFormData((prev) => ({
                                                ...prev,
                                                personal: {
                                                    ...prev.personal,
                                                    gender: formData.personal.gender === gender ? "" : gender,
                                                },
                                            }))}
                                        >
                                            {formData.personal.gender === gender && (
                                                <span className="w-4 h-4 flex items-center justify-center">
                                                    <FaCheck className="h-3 w-3 text-blue-600" />
                                                </span>
                                            )}
                                            <Label htmlFor={`gender-${gender}`} className="font-normal cursor-pointer capitalize">
                                                {gender}
                                            </Label>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>
                    </div>
                );
            case 1:
                return (
                    <div className="space-y-6">
                        <div className="bg-blue-50 p-6 rounded-xl border border-blue-100 shadow-sm">
                            <h3 className="text-xl font-semibold mb-4 text-blue-800 flex items-center">
                                <span className="bg-blue-100 p-2 rounded-lg mr-3">
                                    <FaHome className="h-5 w-5 text-blue-600" />
                                </span>
                                Room Preferences
                            </h3>
                            <div className="mt-6">
                                <Label className="mb-3">Preferred Room Type</Label>
                                <div className="grid grid-cols-2 md:grid-cols-3 gap-3">
                                    {ROOM_TYPES.map((roomType) => (
                                        <div
                                            key={roomType.id}
                                            className={`flex items-center space-x-2 p-3 border rounded cursor-pointer hover:bg-gray-50 ${formData.room.roomType === roomType.id ? "border-blue-500 bg-blue-50" : ""}`}
                                            onClick={() => setFormData((prev) => ({
                                                ...prev,
                                                room: {
                                                    ...prev.room,
                                                    roomType: formData.room.roomType === roomType.id ? "" : roomType.id,
                                                },
                                            }))}
                                        >
                                            {formData.room.roomType === roomType.id && (
                                                <span className="w-4 h-4 flex items-center justify-center">
                                                    <FaCheck className="h-3 w-3 text-blue-600" />
                                                </span>
                                            )}
                                            <Label htmlFor={`roomtype-${roomType.id}`} className="text-sm font-normal cursor-pointer">{roomType.label}</Label>
                                        </div>
                                    ))}
                                </div>
                            </div>

                            <div className="mt-6">
                                <Label className="mb-3">Monthly Budget</Label>
                                <div className="bg-white p-4 rounded-lg border border-blue-200">
                                    <div className="flex items-center justify-center gap-3 mb-4">
                                        <Button
                                            type="button"
                                            variant="outline"
                                            size="icon"
                                            className="w-8 h-8 rounded-full"
                                            onClick={() => handleRoomBudgetChange(Math.max(1500, formData.room.budget - 500))}
                                        >
                                            −
                                        </Button>
                                        <div className="relative">
                                            <span className="absolute left-2 top-1/2 -translate-y-1/2 text-gray-500">₹</span>
                                            <Input
                                                type="number"
                                                min="1500"
                                                max="50000"
                                                value={formData.room.budget}
                                                onChange={(e) => handleRoomBudgetChange(Number(e.target.value))}
                                                className="w-28 pl-6 pr-2 text-center"
                                            />
                                        </div>
                                        <Button
                                            type="button"
                                            variant="outline"
                                            size="icon"
                                            className="w-8 h-8 rounded-full"
                                            onClick={() => handleRoomBudgetChange(Math.min(50000, formData.room.budget + 500))}
                                        >
                                            +
                                        </Button>
                                    </div>
                                    <div className="px-2">
                                        <div className="flex justify-between text-sm mb-2">
                                            <span>₹1,500</span>
                                            <span className="font-bold text-blue-600">₹{formData.room.budget.toLocaleString()}</span>
                                            <span>₹50,000+</span>
                                        </div>
                                        <Slider
                                            value={[formData.room.budget]}
                                            onValueChange={(val) => handleRoomBudgetChange(val[0])}
                                            min={1500}
                                            max={50000}
                                            step={500}
                                            className="w-full"
                                        />
                                        <p className="text-xs text-muted-foreground mt-2 text-center">Slide or use buttons to set your monthly rent budget</p>
                                    </div>
                                </div>
                            </div>

                            <div className="mt-6">
                                <div className="flex items-center justify-between mb-3">
                                    <Label className="mb-0">Amenities Required</Label>
                                    <div className="flex items-center gap-2">
                                        <span className="text-sm text-muted-foreground">
                                            {formData.room.amenities.length} selected
                                        </span>
                                        <Button
                                            type="button"
                                            variant="ghost"
                                            size="sm"
                                            className="text-xs h-7 px-2"
                                            onClick={() => setFormData((prev) => ({ ...prev, room: { ...prev.room, amenities: ROOM_AMENITIES.map(a => a.id) } }))}
                                        >
                                            Select All
                                        </Button>
                                        <Button
                                            type="button"
                                            variant="ghost"
                                            size="sm"
                                            className="text-xs h-7 px-2"
                                            onClick={() => setFormData((prev) => ({ ...prev, room: { ...prev.room, amenities: [] } }))}
                                            disabled={formData.room.amenities.length === 0}
                                        >
                                            Clear All
                                        </Button>
                                    </div>
                                </div>
                                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                                    {ROOM_AMENITIES.map((amenity) => (
                                        <div
                                            key={amenity.id}
                                            className={`flex items-center space-x-2 p-2 border rounded cursor-pointer hover:bg-gray-50 ${formData.room.amenities.includes(amenity.id) ? "border-blue-500 bg-blue-50" : ""}`}
                                            onClick={() => setFormData((prev) => ({
                                                ...prev,
                                                room: {
                                                    ...prev.room,
                                                    amenities: formData.room.amenities.includes(amenity.id)
                                                        ? prev.room.amenities.filter((item) => item !== amenity.id)
                                                        : [...prev.room.amenities, amenity.id],
                                                },
                                            }))}
                                        >
                                            {formData.room.amenities.includes(amenity.id) && (
                                                <span className="w-4 h-4 flex items-center justify-center">
                                                    <FaCheck className="h-3 w-3 text-blue-600" />
                                                </span>
                                            )}
                                            <Label htmlFor={`amenity-${amenity.id}`} className="text-sm font-normal cursor-pointer">{amenity.label}</Label>
                                        </div>
                                    ))}
                                </div>
                            </div>
                        </div>
                    </div>
                );
            case 2:
                return (
                    <div className="space-y-6">
                        <div className="bg-blue-50 p-6 rounded-xl border border-blue-100 shadow-sm">
                            <h3 className="text-lg font-medium mb-4 text-blue-800 flex items-center">
                                <span className="bg-blue-100 p-2 rounded-lg mr-3">
                                    <FaUtensils className="h-5 w-5 text-blue-600" />
                                </span>
                                1. Monthly Mess Budget:
                            </h3>
                            <div className="bg-white p-4 rounded-lg border border-blue-200">
                                <div className="flex items-center justify-center gap-3 mb-4">
                                    <Button
                                        type="button"
                                        variant="outline"
                                        size="icon"
                                        className="w-8 h-8 rounded-full"
                                        onClick={() => handleMessBudgetChange(Math.max(1500, formData.mess.budget - 100))}
                                    >
                                        −
                                    </Button>
                                    <div className="relative">
                                        <span className="absolute left-2 top-1/2 -translate-y-1/2 text-gray-500">₹</span>
                                        <Input
                                            type="number"
                                            min="1500"
                                            max="6000"
                                            value={formData.mess.budget}
                                            onChange={(e) => handleMessBudgetChange(Number(e.target.value))}
                                            className="w-24 pl-6 pr-2 text-center"
                                        />
                                    </div>
                                    <Button
                                        type="button"
                                        variant="outline"
                                        size="icon"
                                        className="w-8 h-8 rounded-full"
                                        onClick={() => handleMessBudgetChange(Math.min(6000, formData.mess.budget + 100))}
                                    >
                                        +
                                    </Button>
                                </div>
                                <div className="px-2">
                                    <div className="flex justify-between text-sm mb-2">
                                        <span>₹1500</span>
                                        <span className="font-bold text-blue-600">₹{formData.mess.budget}</span>
                                        <span>₹6000+</span>
                                    </div>
                                    <Slider
                                        value={[formData.mess.budget]}
                                        onValueChange={(val) => handleMessBudgetChange(val[0])}
                                        min={1500}
                                        max={6000}
                                        step={100}
                                        className="w-full"
                                    />
                                    <p className="text-xs text-muted-foreground mt-2 text-center">Slide or use buttons to adjust your monthly mess budget</p>
                                </div>
                            </div>
                        </div>
                        <div className="bg-green-50 p-6 rounded-xl border border-green-100 shadow-sm">
                            <h3 className="text-lg font-medium mb-4 text-green-800 flex items-center">
                                <span className="bg-green-100 p-2 rounded-lg mr-3">
                                    {formData.mess.foodPref === "vegetarian" ? <FaLeaf className="h-5 w-5 text-green-600" /> : formData.mess.foodPref === "non-veg" ? <FaDrumstickBite className="h-5 w-5 text-red-600" /> : <FaUtensils className="h-5 w-5 text-yellow-600" />}
                                </span>
                                2. Food Preference:
                            </h3>
                            <div className="grid grid-cols-3 gap-4">
                                {[
                                    { id: "vegetarian", label: "Vegetarian", desc: "Pure Veg Meals" },
                                    { id: "non-veg", label: "Non-Veg", desc: "Includes Meat" },
                                    { id: "both", label: "Both", desc: "Flexible Options" },
                                ].map((pref) => (
                                    <div
                                        key={pref.id}
                                        className={`flex flex-col items-center p-4 border rounded cursor-pointer transition-all duration-200 hover:border-green-300 ${formData.mess.foodPref === pref.id ? "border-green-500 bg-green-50" : ""}`}
                                        onClick={() => setFormData((prev) => ({
                                            ...prev,
                                            mess: {
                                                ...prev.mess,
                                                foodPref: formData.mess.foodPref === pref.id ? "" : pref.id,
                                            },
                                        }))}
                                    >
                                        <div className="flex justify-center mb-2">
                                            {pref.id === "vegetarian" && <FaLeaf className="w-8 h-8 text-green-600" />}
                                            {pref.id === "non-veg" && <FaDrumstickBite className="w-8 h-8 text-red-500" />}
                                            {pref.id === "both" && <FaUtensils className="w-8 h-8 text-yellow-500" />}
                                        </div>
                                        {formData.mess.foodPref === pref.id && (
                                            <span className="w-4 h-4 flex items-center justify-center mt-2">
                                                <FaCheck className="h-3 w-3 text-green-600" />
                                            </span>
                                        )}
                                        <p className="text-center font-medium">{pref.label}</p>
                                        <p className="text-center text-sm text-muted-foreground mt-1">{pref.desc}</p>
                                    </div>
                                ))}
                            </div>
                        </div>
                        <div className="bg-purple-50 p-6 rounded-xl border border-purple-100 shadow-sm">
                            <h3 className="text-lg font-medium mb-4 text-purple-800 flex items-center">
                                <span className="bg-purple-100 p-2 rounded-lg mr-3">
                                    <FaTruck className="h-5 w-5 text-purple-600" />
                                </span>
                                3. Service Type:
                            </h3>
                            <div className="grid grid-cols-3 gap-4">
                                {[
                                    { id: "tiffin", label: "Tiffin Delivery", desc: "Delivered to Room" },
                                    { id: "dine-in", label: "Dine-in", desc: "Eat at Mess" },
                                    { id: "any", label: "Any", desc: "No Preference" },
                                ].map((service) => (
                                    <div
                                        key={service.id}
                                        className={`flex flex-col items-center p-4 border rounded cursor-pointer transition-all duration-200 hover:border-purple-300 ${formData.mess.serviceType === service.id ? "border-purple-500 bg-purple-50" : ""}`}
                                        onClick={() => setFormData((prev) => ({
                                            ...prev,
                                            mess: {
                                                ...prev.mess,
                                                serviceType: formData.mess.serviceType === service.id ? "" : service.id,
                                            },
                                        }))}
                                    >
                                        <div className="flex justify-center mb-2">
                                            {service.id === "tiffin" && <FaTruck className="w-8 h-8 text-purple-600" />}
                                            {service.id === "dine-in" && <FaUtensilSpoon className="w-8 h-8 text-purple-600" />}
                                            {service.id === "any" && <FaRandom className="w-8 h-8 text-purple-600" />}
                                        </div>
                                        {formData.mess.serviceType === service.id && (
                                            <span className="w-4 h-4 flex items-center justify-center mt-2">
                                                <FaCheck className="h-3 w-3 text-purple-600" />
                                            </span>
                                        )}
                                        <p className="text-center font-medium">{service.label}</p>
                                        <p className="text-center text-sm text-muted-foreground mt-1">{service.desc}</p>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                );
            case 3:
                return (
                    <div className="space-y-6">
                        <div className="bg-gradient-to-r from-blue-50 to-indigo-50 p-6 rounded-2xl border border-blue-100 shadow-sm">
                            <h3 className="text-xl font-semibold mb-4 text-blue-800 flex items-center">
                                <span className="bg-blue-100 p-2 rounded-lg mr-3">
                                    <FaUser className="h-5 w-5 text-blue-600" />
                                </span>
                                Personal Details
                            </h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div className="bg-white p-3 rounded-lg border border-blue-100">
                                    <p className="text-sm text-muted-foreground">Full Name</p>
                                    <p className="font-medium">{formData.personal.firstName} {formData.personal.lastName}</p>
                                </div>
                                <div className="bg-white p-3 rounded-lg border border-blue-100">
                                    <p className="text-sm text-muted-foreground">Email Address</p>
                                    <p className="font-medium">{formData.personal.email}</p>
                                </div>
                                <div className="bg-white p-3 rounded-lg border border-blue-100">
                                    <p className="text-sm text-muted-foreground">Phone Number</p>
                                    <p className="font-medium">{formData.personal.phone}</p>
                                </div>
                                {formData.personal.altPhone && (
                                    <div className="bg-white p-3 rounded-lg border border-blue-100">
                                        <p className="text-sm text-muted-foreground">Alternative Phone</p>
                                        <p className="font-medium">{formData.personal.altPhone}</p>
                                    </div>
                                )}
                                <div className="bg-white p-3 rounded-lg border border-blue-100">
                                    <p className="text-sm text-muted-foreground">Gender</p>
                                    <p className="font-medium capitalize">{formData.personal.gender}</p>
                                </div>
                                <div className="bg-white p-3 rounded-lg border border-blue-100">
                                    <p className="text-sm text-muted-foreground">College Name</p>
                                    <p className="font-medium">{formData.personal.college}</p>
                                </div>
                                <div className="bg-white p-3 rounded-lg border border-blue-100 col-span-2">
                                    <p className="text-sm text-muted-foreground">Personal Address</p>
                                    <p className="font-medium">{formData.personal.address}</p>
                                </div>
                                <div className="bg-white p-3 rounded-lg border border-blue-100 col-span-2">
                                    <p className="text-sm text-muted-foreground">College Address</p>
                                    <p className="font-medium">{formData.personal.collegeAddress}</p>
                                </div>
                            </div>
                        </div>
                        <div className="bg-gradient-to-r from-green-50 to-emerald-50 p-6 rounded-2xl border border-green-100 shadow-sm">
                            <h3 className="text-xl font-semibold mb-4 text-green-800 flex items-center">
                                <span className="bg-green-100 p-2 rounded-lg mr-3">
                                    <FaHome className="h-5 w-5 text-green-600" />
                                </span>
                                Room Preferences
                            </h3>
                            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                                <div className="bg-white p-3 rounded-lg border border-green-100">
                                    <p className="text-sm text-muted-foreground">Room Type</p>
                                    <p className="font-medium capitalize">{formData.room.roomType || 'N/A'}</p>
                                </div>
                                <div className="bg-white p-3 rounded-lg border border-green-100">
                                    <p className="text-sm text-muted-foreground">Budget</p>
                                    <p className="font-medium">₹{formData.room.budget.toLocaleString()} / month</p>
                                </div>
                                <div className="bg-white p-3 rounded-lg border border-green-100 col-span-2">
                                    <p className="text-sm text-muted-foreground">Amenities</p>
                                    <div className="flex flex-wrap gap-2 mt-1">
                                        {formData.room.amenities.length > 0 ? (
                                            formData.room.amenities.map((item, i) => (
                                                <span key={i} className="bg-green-50 text-green-700 px-3 py-1 rounded-full text-sm font-medium border border-green-100">{item}</span>
                                            ))
                                        ) : (
                                            <span className="text-gray-400 italic">None selected</span>
                                        )}
                                    </div>
                                </div>
                            </div>
                        </div>
                        <div className="bg-gradient-to-r from-purple-50 to-pink-50 p-6 rounded-2xl border border-purple-100 shadow-sm">
                            <h3 className="text-xl font-semibold mb-4 text-purple-800 flex items-center">
                                <span className="bg-purple-100 p-2 rounded-lg mr-3">
                                    <FaUtensils className="h-5 w-5 text-purple-600" />
                                </span>
                                Mess Preferences
                            </h3>
                            <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                                <div className="bg-white p-3 rounded-lg border border-purple-100">
                                    <p className="text-sm text-muted-foreground">Budget</p>
                                    <p className="font-medium">₹{formData.mess.budget} / month</p>
                                </div>
                                <div className="bg-white p-3 rounded-lg border border-purple-100">
                                    <p className="text-sm text-muted-foreground">Food Preference</p>
                                    <p className="font-medium capitalize">{formData.mess.foodPref}</p>
                                </div>
                                <div className="bg-white p-3 rounded-lg border border-purple-100">
                                    <p className="text-sm text-muted-foreground">Service Type</p>
                                    <p className="font-medium capitalize">{formData.mess.serviceType}</p>
                                </div>
                            </div>
                        </div>
                    </div>
                );
            default:
                return null;
        }
    };

    if (isInitialLoad) return (
        <div className="min-h-screen bg-muted flex items-center justify-center">
            <div className="space-y-4 w-full max-w-md">
                <div className="h-8 w-48 bg-gray-200 rounded animate-pulse mx-auto"></div>
                <div className="h-64 bg-gray-200 rounded-xl animate-pulse"></div>
            </div>
        </div>
    );

    return (
        <div className="min-h-screen bg-muted p-4 sm:p-6">
            <div className="max-w-5xl mx-auto">
                <div className="text-center mb-8">
                    <h1 className="text-2xl sm:text-3xl font-bold text-gray-800">Complete Your Profile</h1>
                    <p className="text-muted-foreground mt-2">Tell us about your preferences so we can find the best match for you.</p>
                </div>

                <div className="w-full px-2 mb-8">
                    <StepProgress steps={steps.length} currentStep={currentStep} labels={steps.map(s => s.title)} />
                </div>

                <div className="grid grid-cols-1 lg:grid-cols-4 gap-6">
                    <div className="lg:col-span-1">
                        <Card>
                            <CardContent className="pt-6">
                                <div className="text-center mb-4">
                                    <div className="w-24 h-24 rounded-full bg-orange-100 flex items-center justify-center mx-auto mb-2">
                                        <FaUser className="text-2xl text-orange-600" />
                                    </div>
                                    <h3 className="font-bold">{formData.personal.firstName} {formData.personal.lastName}</h3>
                                    <p className="text-sm text-muted-foreground">Student</p>
                                </div>
                                <div className="mb-4">
                                    <h4 className="text-sm font-medium mb-1">COMPLETION STATUS</h4>
                                    <Progress value={(currentStep / (steps.length - 1)) * 100} className="h-2.5" />
                                    <p className="text-xs text-muted-foreground mt-1">{Math.round((currentStep / (steps.length - 1)) * 100)}%</p>
                                </div>
                                {steps.map((step, index) => (
                                    <div key={step.id} className="flex items-center mb-2">
                                        <span className={`w-4 h-4 rounded-full mr-2 ${index < currentStep ? "bg-green-600" : index === currentStep ? "bg-green-500" : "bg-gray-300"}`}></span>
                                        <span className={index <= currentStep ? "font-medium" : ""}>{step.title}</span>
                                    </div>
                                ))}
                            </CardContent>
                        </Card>
                    </div>

                    <div className="lg:col-span-3">
                        <Card>
                            <CardContent className="pt-6">
                                {renderStepContent()}
                                <div className="flex justify-between mt-8">
                                    <div className="flex gap-3">
                                        {currentStep > 0 && (
                                            <Button variant="outline" onClick={handleBack}>← Back</Button>
                                        )}
                                        <Button variant="outline" onClick={handleSaveDraft} disabled={loading}>
                                            {loading ? "Saving..." : "Save as Draft"}
                                        </Button>
                                    </div>
                                    {currentStep < steps.length - 1 ? (
                                        <Button onClick={handleNext}>Next: {steps[currentStep + 1]?.title} →</Button>
                                    ) : (
                                        <Button onClick={handleSubmit} disabled={loading}>
                                            {loading ? "Submitting..." : "✓ Submit Profile"}
                                        </Button>
                                    )}
                                </div>
                            </CardContent>
                        </Card>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default ProfileCompletePage;
