import React from "react";
import { cn } from '../../lib/utils';
import { FaCheck } from 'react-icons/fa';

const StepProgress = ({ steps, currentStep, labels }) => {
    return (
        <div className="flex justify-center mb-8">
            <div className="flex items-center w-full max-w-4xl">
                {Array.from({ length: steps }).map((_, i) => {
                    const isCompleted = i < currentStep;
                    const isActive = i === currentStep;
                    const label = labels?.[i] || `Step ${i + 1}`;

                    return (
                        <React.Fragment key={i}>
                            <div className="flex flex-col items-center">
                                <div
                                    className={cn(
                                        "w-12 h-12 rounded-full flex items-center justify-center border-2 text-sm font-medium transition-colors",
                                        isCompleted || isActive
                                            ? "bg-green-600 text-white border-green-600"
                                            : "bg-white border-gray-300 text-gray-400"
                                    )}
                                >
                                    {isCompleted ? <FaCheck className="h-4 w-4" /> : i + 1}
                                </div>
                                <span
                                    className={cn(
                                        "mt-2 text-sm font-medium",
                                        isCompleted || isActive ? "text-green-600" : "text-gray-400"
                                    )}
                                >
                                    {label}
                                </span>
                            </div>
                            {i < steps - 1 && (
                                <div
                                    className={cn(
                                        "flex-1 h-1 mx-4",
                                        isCompleted ? "bg-green-600" : "bg-gray-300"
                                    )}
                                />
                            )}
                        </React.Fragment>
                    );
                })}
            </div>
        </div>
    );
};

export { StepProgress };
